CREATE TABLE directory_provisionings (tenant_id VARCHAR(64) NOT NULL, connection_id VARBINARY(255) NOT NULL, doc LONGTEXT NOT NULL, admin_grant LONGBLOB NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, last_sync_at BIGINT NULL, last_sync_status VARCHAR(32) NOT NULL, last_sync_error TEXT NOT NULL, sync_id VARCHAR(64) NOT NULL, next_sync_at BIGINT NULL, lease_until BIGINT NULL, PRIMARY KEY (tenant_id,connection_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE INDEX directory_provisionings_due ON directory_provisionings (next_sync_at);
CREATE TABLE directory_synchronized_groups (tenant_id VARCHAR(64) NOT NULL, connection_id VARBINARY(255) NOT NULL, group_id VARCHAR(32) NOT NULL, doc LONGTEXT NOT NULL, PRIMARY KEY (tenant_id,connection_id,group_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
